from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Find background regions; only regions not connected to the edge are cavities.
    seen = [[False] * w for _ in range(h)]
    region_id = [[-1] * w for _ in range(h)]
    regions = []
    for sr in range(h):
        for sc in range(w):
            if grid[sr][sc] != 0 or seen[sr][sc]:
                continue
            q = deque([(sr, sc)])
            seen[sr][sc] = True
            cells = []
            edge = False
            while q:
                r, c = q.popleft()
                cells.append((r, c))
                if r == 0 or c == 0 or r == h-1 or c == w-1:
                    edge = True
                for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and not seen[nr][nc]:
                        seen[nr][nc] = True
                        q.append((nr, nc))
            rid = len(regions)
            for r, c in cells:
                region_id[r][c] = rid
            regions.append((cells, edge))

    # Paint only the one-cell 8-neighbour rim around a closed cavity: inside 3,
    # outside 2. Deeper cells of a large cavity remain empty.
    for cells, edge in regions:
        if edge:
            continue
        cavity = set(cells)
        rim = set()
        for r, c in cells:
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 1:
                        # cavity has a neighboring boundary, record its neighboring zeros too
                        pass
        boundary = set()
        for r, c in cells:
            for dr in (-1,0,1):
                for dc in (-1,0,1):
                    nr,nc=r+dr,c+dc
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 1:
                        boundary.add((nr,nc))
        for r,c in boundary:
            for dr in (-1,0,1):
                for dc in (-1,0,1):
                    nr,nc=r+dr,c+dc
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0:
                        out[nr][nc] = 3 if region_id[nr][nc] >= 0 and not regions[region_id[nr][nc]][1] else 2
    return out
